def depth_of_dict(d):
    if not d:
        return 0
    else:
        return max(depth_of_dict(d.get(k, {})) + 1 for k in d)

import re
def check_literals(text, patterns):
  for pattern in patterns:
    if re.search(pattern,  text):
        return ('Matched!')
    else:
        return ('Not Matched!')

def sum_digits(n):
  if n == 0:
    return 0
  else:
    return n % 10 + sum_digits(int(n / 10))

def odd_days(year):
    """
    Calculate the number of odd days in a given year.
    """
    days = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    return sum(days[1:13] if year % 4 == 0 else days[2:14])

def dict_depth(d):
    """
    Returns the maximum depth of a dictionnary
    """
    max_depth = 0
    for key, value in d.items():
        if isinstance(value, dict):
            curr_depth = dict_depth(value) + 1
            max_depth = max(max_depth, curr_depth)
    return max_depth

def equilibrium_index(arr):
  total_sum = sum(arr)
  left_sum=0
  for i, num in enumerate(arr):
    total_sum -= num
    if left_sum == total_sum:
      return i
    left_sum += num
  return -1

