def fibonacci(n):
    if n <= 1:
        return n
    else:
        return fibonacci(n-1) + fibonacci(n-2)

def modify_rle(seq):
    # Initialize an empty dictionary to store the modified RLE
    modified_rle = {}

    # Iterate through the sequence
    for i, element in enumerate(seq):
        # If the current element is not the same as the previous element, or we haven't seen it before
        if i > 0 and seq[i - 1] != element or element not in modified_rle:
            # Add the current element to the dictionary with its count
            modified_rle[element] = 1 + (modified_rle.get(element, 0))

    return modified_rle

