def remove_character(s, c):
    """
    Returns a copy of the string 's' with all occurrences of 'c' removed.
    """
    return ''.join([x for x in s if x != c])

def count_substrings(s):
    char_dict = {}
    for char in s:
        char_dict[char] = char_dict.get(char, 0) + 1

    count = 0
    for char in s:
        if char_dict[char] > 1:
            count += char_dict[char] * (char_dict[char] - 1) // 2

    return count

