def find_min_length_sub_list(lst):
    min_len = len(lst)
    min_sub_list = lst
    for i in range(len(lst)):
        for j in range(i+1, len(lst)):
            if lst[i:j] == lst[i:j][::-1]:
                if len(lst[i:j]) < min_len:
                    min_len = len(lst[i:j])
                    min_sub_list = lst[i:j]
    return min_sub_list

def find_Sum(arr,n): 
    arr.sort() 
    sum = arr[0] 
    for i in range(0,n-1): 
        if (arr[i] != arr[i+1]): 
            sum = sum + arr[i+1]   
    return sum

def sum_even_odd(numbers):
    even_sum = 0
    odd_sum = 0
    for num in numbers:
        if num % 2 == 0:
            even_sum += num
        else:
            odd_sum += num
    return even_sum + odd_sum

def roman_to_int(roman):
    roman_dict = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    result = 0
    prev_value = 0
    for char in roman:
        current_value = roman_dict[char]
        if current_value > prev_value:
            result += current_value - 2 * prev_value
        else:
            result += current_value
        prev_value = current_value
    return result

